@verbatim
<!DOCTYPE html>
<html lang="nl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Welke verlichting? – Boels Industrial</title>
<style>
  :root{
    --ink:#1b1f23;--graphite:#3d454d;--fog:#eef0f2;--paper:#f7f8f9;--line:#d5d9de;
    --orange:#f07d00;--orange-deep:#c76600;--ok:#1f8a4c;--warn:#d9a400;--bad:#c8341f;--glow:#ffd166;
    --mono:"IBM Plex Mono","SFMono-Regular",Consolas,monospace;
    --sans:"IBM Plex Sans","Segoe UI",Helvetica,Arial,sans-serif;
    --cond:"Barlow Condensed","Arial Narrow","Helvetica Neue",Arial,sans-serif;
  }
  *{box-sizing:border-box}
  [hidden]{display:none!important}
  html,body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:16px;line-height:1.45}
  header{background:var(--ink);color:#fff;padding:0 28px 0 0;display:flex;align-items:center;gap:22px;flex-wrap:wrap}
  header .logo{background:#fff;padding:10px 22px;display:flex;align-items:center;align-self:stretch}
  header .logo img{height:44px;width:auto;display:block}
  header .brand{font-family:var(--cond);font-weight:700;font-size:15px;letter-spacing:.14em;text-transform:uppercase;color:var(--orange)}
  header h1{font-family:var(--cond);font-weight:600;font-size:30px;margin:0;text-transform:uppercase}
  header .sub{color:#aab2ba;font-size:13px;margin-left:auto}
  main{max-width:1100px;margin:0 auto;padding:24px 20px 60px;display:grid;grid-template-columns:400px 1fr;gap:24px}
  @media(max-width:900px){main{grid-template-columns:1fr}}
  .step{background:#fff;border:1px solid var(--line);border-radius:6px;padding:18px 20px;margin-bottom:14px}
  .step h2{font-family:var(--cond);text-transform:uppercase;letter-spacing:.08em;font-size:15px;font-weight:700;color:var(--graphite);margin:0 0 12px;display:flex;gap:10px;align-items:center}
  .step h2 .n{display:inline-flex;width:26px;height:26px;border-radius:50%;background:var(--orange);color:#fff;align-items:center;justify-content:center;font-size:14px}
  .choices{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}
  .choices button{font:inherit;font-family:var(--cond);font-weight:700;font-size:18px;line-height:1.15;padding:11px 8px;border:2px solid var(--line);border-radius:6px;background:#fff;color:var(--graphite);cursor:pointer;text-align:left}
  .choices button small{display:block;font-family:var(--sans);font-weight:400;font-size:12px;color:#6b737b;margin-top:2px}
  .choices button.on{border-color:var(--ink);background:var(--ink);color:#fff}
  .choices button.on small{color:#cfd5da}
  .field label{display:block;font-size:12px;font-weight:600;color:var(--graphite);text-transform:uppercase;letter-spacing:.06em;margin-bottom:5px}
  .field input,.field select{width:100%;font:inherit;font-family:var(--mono);font-size:20px;padding:10px 12px;border:1px solid var(--line);border-radius:4px;background:var(--paper);color:var(--ink)}
  .field input:focus,.field select:focus,button:focus-visible{outline:2px solid var(--orange);outline-offset:1px}
  .row{display:grid;grid-template-columns:1fr auto 1fr;gap:8px;align-items:end}
  .row .x{font-family:var(--cond);font-size:24px;color:#6b737b;padding-bottom:8px}
  .hint{font-size:12px;color:#6b737b;margin-top:6px}
  .toggle{display:flex;align-items:center;gap:10px;font-size:14px;margin-top:10px;cursor:pointer}
  .toggle input{width:18px;height:18px;accent-color:var(--orange)}
  details{border-top:1px dashed var(--line);margin-top:12px;padding-top:10px}
  summary{cursor:pointer;font-size:13px;font-weight:600;color:var(--graphite)}
  details .field{margin-top:10px}
  details .field input,details .field select{font-size:15px;padding:7px 10px}

  .verdict{background:var(--ink);color:#fff;border-radius:6px;padding:20px 24px;position:relative;overflow:hidden;margin-bottom:14px}
  .verdict .stripe{position:absolute;left:0;top:0;bottom:0;width:6px;background:var(--glow)}
  .verdict .eyebrow{font-family:var(--cond);text-transform:uppercase;letter-spacing:.12em;font-size:13px;color:#aab2ba}
  .verdict .big{font-family:var(--cond);font-weight:700;font-size:38px;line-height:1.05;margin:6px 0 4px}
  .verdict .why{font-size:15px;color:#cfd5da;max-width:64ch}

  .plan{background:#fff;border:1px solid var(--line);border-radius:6px;padding:16px 18px;margin-bottom:14px;display:grid;grid-template-columns:1fr 200px;gap:16px;align-items:center}
  @media(max-width:600px){.plan{grid-template-columns:1fr}}
  .plan svg{width:100%;height:auto;display:block}
  .plan .facts .k{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#6b737b;font-weight:600;margin-top:8px}
  .plan .facts .v{font-family:var(--mono);font-size:20px}
  .plan .facts .v small{font-size:12px;color:#6b737b}

  .opt{background:#fff;border:1px solid var(--line);border-radius:6px;overflow:hidden;margin-bottom:14px}
  .opt .head{display:flex;align-items:center;gap:12px;padding:12px 18px;background:var(--fog)}
  .opt .head .rank{font-family:var(--cond);font-weight:700;font-size:13px;letter-spacing:.1em;text-transform:uppercase;color:#fff;background:var(--orange);padding:3px 8px;border-radius:3px}
  .opt .head h3{font-family:var(--cond);font-size:18px;margin:0;color:var(--ink);flex:1}
  .opt .head button{font:inherit;font-size:13px;font-weight:600;padding:6px 12px;border:1px solid var(--ink);border-radius:4px;background:#fff;cursor:pointer}
  .opt .head button:active{background:var(--ink);color:#fff}
  .line{display:grid;grid-template-columns:64px 110px 1fr;gap:12px;align-items:center;padding:12px 18px;border-top:1px solid var(--line)}
  .line .qty{font-family:var(--cond);font-weight:700;font-size:28px;text-align:right}
  .line .qty small{font-size:14px;color:#6b737b;font-weight:600}
  .line .grp{font-family:var(--mono);font-size:22px;font-weight:600;color:var(--orange-deep)}
  .line .desc{font-size:14px;line-height:1.3}
  .line .desc b{display:block;font-family:var(--cond);font-size:17px;font-weight:700}
  .line.note{grid-template-columns:1fr;background:#fff8f3;font-size:13px;color:var(--graphite)}
  .line.sub .qty,.line.sub .grp{font-size:18px}
  .line.sub{background:#fbfbfc}
  .notes{font-size:12px;color:#6b737b;line-height:1.5}
  .toast{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:var(--ink);color:#fff;padding:10px 18px;border-radius:999px;font-size:14px;opacity:0;transition:opacity .2s;pointer-events:none}
  .toast.show{opacity:1}
  @media(prefers-reduced-motion:reduce){*{transition:none!important}}
</style>
</head>
<body>
<header>
  <a class="logo" href="#" aria-label="Boels Industrial"><img src="data:image/png;base64," alt="Boels Industrial"></a>
  <h1>Welke verlichting?</h1>
  <span class="sub">Lichtmasten, bouwlampen en 42 V-verlichting uit de materieellijst</span>
  <a href="/launcher" style="color:#aab2ba;font-size:13px;text-decoration:none;border:1px solid #3d454d;border-radius:6px;padding:6px 12px;align-self:center;">&larr; Terug naar dashboard</a>
</header>

<main>
<section aria-label="Invoer">
  <div class="step">
    <h2><span class="n">1</span>Waar wordt gewerkt?</h2>
    <div class="choices" id="where">
      <button data-w="out" class="on">Buitenterrein<small>bouwplaats, tankput, laadplaats</small></button>
      <button data-w="in">Binnen<small>hal, ruimte, containment</small></button>
      <button data-w="tank">In een tank / besloten ruimte<small>42 V veiligheidsspanning</small></button>
      <button data-w="path">Looppad / steiger<small>lichtsnoer</small></button>
    </div>
    <label class="toggle"><input type="checkbox" id="ex"> Het is een EX / ATEX-zone</label>
  </div>

  <div class="step">
    <h2><span class="n">2</span>Hoe groot?</h2>
    <div id="areaIn">
      <div class="row">
        <div class="field"><label for="lenA">Lengte (m)</label><input id="lenA" type="number" min="1" step="1" value="40"></div>
        <div class="x">×</div>
        <div class="field"><label for="widA">Breedte (m)</label><input id="widA" type="number" min="1" step="1" value="25"></div>
      </div>
      <div class="hint" id="areaTxt"></div>
    </div>
    <div id="pathIn" class="field" hidden>
      <label for="lenP">Lengte van het pad (m)</label><input id="lenP" type="number" min="1" step="5" value="60">
    </div>
  </div>

  <div class="step">
    <h2><span class="n">3</span>Wat voor werk?</h2>
    <div class="choices" id="task">
      <button data-lux="20">Zien en veilig lopen<small>opslag, verkeer, bewaking · 20 lux</small></button>
      <button data-lux="50">Grof werk<small>laden/lossen, grondwerk · 50 lux</small></button>
      <button data-lux="150" class="on">Bouw en onderhoud<small>montage, steigerwerk · 150 lux</small></button>
      <button data-lux="400">Precisie en inspectie<small>lassen, meten, inspectie · 400 lux</small></button>
    </div>
  </div>

  <div class="step">
    <h2><span class="n">4</span>Stroom ter plaatse?</h2>
    <div class="choices" id="power">
      <button data-p="230" class="on">230 V aanwezig</button>
      <button data-p="400">400 V aanwezig</button>
      <button data-p="none">Geen stroom<small>diesel, hybride, solar, accu</small></button>
    </div>
    <details>
      <summary>Geavanceerd</summary>
      <div class="field"><label for="lux">Eigen luxwaarde</label><input id="lux" type="number" min="5" step="10" placeholder="leeg = keuze hierboven"></div>
      <div class="field"><label for="uf">Rendement (hoeveel licht op de werkplek landt)</label>
        <select id="uf"><option value="auto" selected>Automatisch per situatie</option><option value="0.3">30 % – open terrein, hoge masten</option><option value="0.45">45 % – normaal</option><option value="0.6">60 % – lichte wanden, laag gehangen</option></select></div>
    </details>
  </div>
</section>

<section aria-live="polite" id="out">
  <div class="verdict" id="verdict"><div class="stripe"></div><div class="eyebrow">Advies</div><div class="big" id="vBig">—</div><div class="why" id="vWhy"></div></div>
  <div class="plan" id="plan"><div id="planSvg"></div><div class="facts" id="planFacts"></div></div>
  <div id="opts"></div>
  <p class="notes">Rekenwijze: benodigde lichtstroom = lux × oppervlak ÷ (rendement × 0,8 onderhoudsfactor). Lumen per armatuur is geschat uit het vermogen (120 lm/W schijnwerpers, 130 lm/W masten, 100 lm/W buizen en 42 V) en staat bovenin het script per groepsnummer; vervang door leveranciersdata waar bekend. Luxniveaus volgens NEN-EN 12464-2 (buiten) en -1 (binnen). Richtwaarde voor de binnendienst.</p>
</section>
</main>
<div class="toast" id="toast">Gekopieerd</div>

<script>
(() => {
/* ==============================================================
   VERLICHTING UIT DE MATERIEELLIJST (12-08-2026)
   lm = geschatte lichtstroom per armatuur (aanpassen naar leveranciersdata)
   W  = opgenomen vermogen · sup = voeding: self | 230 | 400 | 42 | bat
   use = out | in | tank | path · ex = EX-uitvoering
   ============================================================== */
const P = [
  // Lichtmasten – zelfvoorzienend
  {g:'74055',d:'Lighting tower diesel generator 4x300W LED mobile',lm:156000,W:1200,sup:'self',use:['out'],tip:'Werkpaard voor grote terreinen; stroomvoorziening zit erin'},
  {g:'12537',d:'Lighting tower generator, hydraulic',lm:156000,W:1200,sup:'self',use:['out'],tip:'Hydraulische mast, geschat 4x300W'},
  {g:'12539',d:'Lighting tower generator, ECO hydraulic',lm:156000,W:1200,sup:'self',use:['out'],tip:'Zuinige variant, geschat 4x300W'},
  {g:'12601',d:'Lighting tower generator, LED 6x150W',lm:117000,W:900,sup:'self',use:['out']},
  {g:'12535',d:'Hybrid light tower generator with LED',lm:78000,W:600,sup:'self',use:['out'],tip:'Stil en zuinig: accu overdag laden, ’s nachts stil branden; geschat 600W'},
  {g:'12648',d:'Light pole Hybrid Lithium stationary 6x100W',lm:78000,W:600,sup:'self',use:['out'],tip:'Stationair, accu/hybride'},
  {g:'12649',d:'Lightning tower Solar LED 4x65W',lm:34000,W:260,sup:'self',use:['out'],tip:'Geen brandstof; alleen voor lage lichteisen'},
  // Lichtmasten op net
  {g:'74046',d:'Lighting tower stationary 230V 4x160W LED 8.5m',lm:83000,W:640,sup:'230',use:['out']},
  {g:'74050',d:'Lighting tower stationary 230V 4x160W LED 8m',lm:83000,W:640,sup:'230',use:['out']},
  {g:'12602',d:'Lighting tower, interconnectible, 4x150 W LED',lm:78000,W:600,sup:'230',use:['out','in'],tip:'Doorkoppelbaar: één voedingspunt voor meerdere masten'},
  {g:'12127',d:'Lighting mast 4.3m 420W LED',lm:55000,W:420,sup:'230',use:['out','in']},
  {g:'74053',d:'Lighting tower 1x400W Powerdisk mobile',lm:52000,W:400,sup:'230',use:['out','in']},
  {g:'12543',d:'Lightingballoon 600W LED incl. tripod and flightcase',lm:72000,W:600,sup:'230',use:['in','out'],tip:'Verblindingsvrij rondom licht, ideaal in hallen en bij nachtwerk'},
  // Schijnwerpers en bouwlampen 230V
  {g:'12508',d:'Floodlight 500W LED incl. tripod',lm:60000,W:500,sup:'230',use:['out','in']},
  {g:'74024',d:'Floodlight LED 230V 180W',lm:21600,W:180,sup:'230',use:['out','in']},
  {g:'74011',d:'Floodlight LED 230V 129W',lm:15500,W:129,sup:'230',use:['out','in']},
  {g:'74028',d:'Floodlight LED 230V 90W',lm:10800,W:90,sup:'230',use:['out','in']},
  {g:'74027',d:'Floodlight LED 230V 60W on hand-held tripod',lm:7200,W:60,sup:'230',use:['in','out']},
  {g:'74036',d:'Construction lamp LED 230V 38W linkable',lm:3800,W:38,sup:'230',use:['in'],tip:'Doorkoppelbaar, voor gangen en kleine ruimtes'},
  {g:'15075',d:'Working light 360° 84W LED dimmable on battery',lm:8400,W:84,sup:'bat',use:['in','out'],tip:'Accu, rondom licht; nachtwerk zonder stroom'},
  {g:'5263524',d:'Floodlight 75W LED dimmable battery',lm:9000,W:75,sup:'bat',use:['in','out']},
  // 42 V – tank en besloten ruimte
  {g:'74029',d:'Floodlight for tank lighting LED 42V 120W',lm:12000,W:120,sup:'42',use:['tank'],tip:'Speciaal voor tanks'},
  {g:'74031',d:'Floodlight LED 60W 42V linkable',lm:6000,W:60,sup:'42',use:['tank','in'],tip:'Doorkoppelbaar'},
  {g:'74030',d:'Floodlight LED 42V 30W',lm:3000,W:30,sup:'42',use:['tank']},
  {g:'74022',d:'LED light tube 42V 30W linkable',lm:3000,W:30,sup:'42',use:['tank','path'],tip:'Doorkoppelbaar, gelijkmatig licht in nauwe ruimtes'},
  {g:'74043',d:'Construction lamp LED 42V 3x40W',lm:12000,W:120,sup:'42',use:['tank']},
  // EX – 230V
  {g:'86617',d:'Lighting tower stationary EX 230V 4x80W LED 8.5m',lm:38000,W:320,sup:'230',use:['out'],ex:true},
  {g:'75026',d:'Lighting tower stationary EX 230V 4x50W LED 8.5m CEAG 3P',lm:24000,W:200,sup:'230',use:['out'],ex:true},
  {g:'75016',d:'Floodlight EX LED 230V 165W in mobile frame',lm:19800,W:165,sup:'230',use:['out','in'],ex:true},
  {g:'75014',d:'Floodlight EX LED 230V 150W with 10m cable',lm:18000,W:150,sup:'230',use:['out','in'],ex:true},
  {g:'75021',d:'Floodlight EX LED 230V 50W with 10m cable linkable',lm:6000,W:50,sup:'230',use:['in','out'],ex:true,tip:'Doorkoppelbaar'},
  {g:'75007',d:'LED light EX tube 230V 25W with 10m cable linkable',lm:2500,W:25,sup:'230',use:['path','in'],ex:true,tip:'Doorkoppelbaar'},
  {g:'75003',d:'Construction lamp EX LED 31W battery',lm:3100,W:31,sup:'bat',use:['in','tank'],ex:true},
  // EX – 42 V
  {g:'75019',d:'Floodlight EX LED 24-42V 68W with 10m cable',lm:6800,W:68,sup:'42',use:['tank','in'],ex:true},
  {g:'71623',d:'Floodlight EX LED 42V 50W with. 10m cable linkable',lm:5000,W:50,sup:'42',use:['tank','in'],ex:true,tip:'Doorkoppelbaar'},
  {g:'75010',d:'LED light EX tube 42V 25W with 10m cable linkable',lm:2500,W:25,sup:'42',use:['tank','path'],ex:true,tip:'Doorkoppelbaar'},
  {g:'75025',d:'Construction lamp EX LED 42V 3x30W linkable',lm:9000,W:90,sup:'42',use:['tank'],ex:true},
];
// Lichtsnoeren voor looppaden: lengte per snoer, lux indicatief
const PATHS = [
  {g:'81474',d:'Lighting cable 24m 5xLED 230V 12W magnets DL',len:24,W:60,sup:'230',tip:'Magneten: hangt zo aan steiger of leuning'},
  {g:'81574',d:'Lighting cable 20m 6xLED 12-24V 12W DL',len:20,W:72,sup:'24',tip:'Laagspanning, trafo nodig'},
  {g:'52630233',d:'Led Strip Interconnectable with Afterglow 15m 42V',len:15,W:30,sup:'42',tip:'Nalichtend: blijft zichtbaar bij stroomuitval, doorkoppelbaar'},
];
const PATHS_EX = [
  {g:'75010',d:'LED light EX tube 42V 25W with 10m cable linkable',len:10,W:25,sup:'42',tip:'Om de 10 m een buis, doorgekoppeld'},
  {g:'75007',d:'LED light EX tube 230V 25W with 10m cable linkable',len:10,W:25,sup:'230',tip:'Om de 10 m een buis, doorgekoppeld'},
];
// Trafo's 230/400 V > 42 V. va = vermogen, out = aantal 42 V-uitgangen
const TR = [
  {g:'81593',d:'Transformer 230V > 2x42V AC 16A 600VA',va:600,out:2,in:'230'},
  {g:'81603',d:'Transformer 230V > 4x42VAC 16A 1000VA',va:1000,out:4,in:'230'},
  {g:'81600',d:'Transformer 230V > 4x42V AC 16A 1300VA',va:1300,out:4,in:'230'},
  {g:'81601',d:'Transformer 230V > 4x42V AC 16A 2000VA',va:2000,out:4,in:'230'},
  {g:'81605',d:'Transformer 230V > 6x42V AC 16A 2000VA',va:2000,out:6,in:'230'},
  {g:'81606',d:'Transformer 230V > 6x42V AC 16A 3000VA',va:3000,out:6,in:'230'},
  {g:'81614',d:'Transformer 400V > 8x42V 16A 2000VA',va:2000,out:8,in:'400'},
  {g:'81611',d:'Transformer 400V > 6x42V 16A 3000VA',va:3000,out:6,in:'400'},
  {g:'81616',d:'Transformer 400V 32A > 6x42V AC 32A 6000VA',va:6000,out:6,in:'400'},
];
const TR_EX = [
  {g:'81484',d:'Transformer EX 400VA 230V > 2x42V AC 16A linkable',va:400,out:2,in:'230'},
  {g:'81480',d:'Transformer EX 400VA 230V > 3x42V AC 16A',va:400,out:3,in:'230'},
  {g:'81482',d:'Transformer EX 400VA 230V > 4x42V AC 16A',va:400,out:4,in:'230'},
  {g:'81483',d:'Transformer EX 1200VA 230V > 8x42V AC 16A',va:1200,out:8,in:'230'},
];
const TR24 = {g:'81597',d:'Transformer 230V > 4x24V 600VA',va:600,out:4};
const CAB42 = {g:'81541',d:'Extension cable 42V 16A 25m 2x2.5mm²'};
const CAB42_EX = {g:'71806',d:'Extension cable EX 42V 16A 25m 3x2.5mm²'};
const SPLIT42 = {g:'81645',d:'Distribution box 42V 16A 2p - 4x42V 16A 2p'};
const CAB230 = {g:'81514',d:'Extension cable 230V 16A 25m 3x2.5mm² CEE'};
const CAB230_EX = {g:'71797',d:'Extension cable EX 230V 16A 25m 3x2.5mm²'};

const MF = 0.8;           // onderhoudsfactor
const UF = {out:0.35,in:0.55,tank:0.45};
const $=id=>document.getElementById(id);
const S={where:'out',lux:150,power:'230'};
const f0=n=>n.toLocaleString('nl-NL',{maximumFractionDigits:0});
const f1=n=>n.toLocaleString('nl-NL',{maximumFractionDigits:1});

/* ---------- voeding per optie ---------- */
function supply(sup,n,W,ex){
  const tot=n*W, lines=[], notes=[];
  if(sup==='self') notes.push('Zelfvoorzienend – geen stroomaansluiting nodig.');
  else if(sup==='bat') notes.push('Accu-armaturen: laadpunt 230 V voor de laders regelen.');
  else if(sup==='230'){
    const groups=Math.ceil(tot/3000);
    notes.push(`Totaal ${f0(tot)} W op 230 V → ${groups} groep${groups>1?'en':''} van 16 A.`);
    lines.push({qty:n,...(ex?CAB230_EX:CAB230),sub:'richtaantal: één per armatuur'});
  } else if(sup==='42'){
    const list=ex?TR_EX:TR;
    const need=tot/0.9, outlets=Math.ceil(tot/600);
    let tr=list.filter(t=>t.va>=need&&t.out>=outlets&&(S.power==='400'?true:t.in==='230')).sort((a,b)=>a.va-b.va)[0];
    let qty=1;
    if(!tr){ // meerdere van de grootste
      tr=list.filter(t=>S.power==='400'?true:t.in==='230').sort((a,b)=>b.va-a.va)[0];
      qty=Math.max(Math.ceil(need/tr.va),Math.ceil(outlets/tr.out));
    }
    lines.push({qty,...tr,sub:`${f0(tot)} W aan 42 V-lampen, ${outlets} uitgang${outlets>1?'en':''} nodig (max. 600 W per uitgang)`});
    lines.push({qty:outlets,...(ex?CAB42_EX:CAB42),sub:'één per gebruikte trafo-uitgang'});
    if(n>outlets&&!ex) lines.push({qty:outlets,...SPLIT42,sub:'als de lampen niet doorkoppelbaar zijn'});
    notes.push(`Trafo op ${S.power==='400'&&tr.in==='400'?'400 V':'230 V'} aansluiten, buiten de tank.`);
  } else if(sup==='24'){
    const qty=Math.max(1,Math.ceil(tot/0.9/TR24.va));
    lines.push({qty,...TR24,sub:'24 V-trafo voor de lichtsnoeren'});
  }
  return {lines,notes,tot};
}

/* ---------- hoofdberekening ---------- */
function render(){
  const ex=$('ex').checked, where=S.where;
  $('areaIn').hidden=where==='path'; $('pathIn').hidden=where!=='path';
  const opts=$('opts'); opts.innerHTML='';
  const lux=+$('lux').value||S.lux;

  if(where==='path'){
    const L=+$('lenP').value||0;
    $('vBig').textContent='Lichtsnoer langs het pad';
    $('vWhy').textContent=`${L} m looppad: doorgekoppelde snoeren of buizen, één voedingspunt.`;
    $('planSvg').innerHTML=pathSvg(L); $('planFacts').innerHTML=`<div class="k">Lengte</div><div class="v">${L} <small>m</small></div>`;
    const list=(ex?PATHS_EX:PATHS).filter(p=>S.power!=='none'||p.sup==='bat');
    list.forEach((p,i)=>{
      const n=Math.ceil(L/p.len);
      const sp=supply(p.sup,n,p.W,ex);
      option(opts,i,`${n}× ${p.d.split(' with')[0]}`,[{qty:n,...p,sub:`${p.len} m per stuk · ${p.tip||''}`},...sp.lines],sp.notes);
    });
    if(!list.length) option(opts,0,'Zonder stroom',[],['Gebruik accu-armaturen (15075 / 5263524) of een kleine generator voor het lichtsnoer.']);
    return;
  }

  const Lm=+$('lenA').value||0, Bm=+$('widA').value||0, A=Lm*Bm;
  $('areaTxt').textContent=A?`${f0(A)} m²`:'';
  const uf=$('uf').value==='auto'?UF[where]:+$('uf').value;
  const needLm=lux*A/(uf*MF);
  if(!A){$('vBig').textContent='—';$('vWhy').textContent='Vul lengte en breedte in.';return;}

  // kandidaten
  let cand=P.filter(p=>p.use.includes(where)&&!!p.ex===ex);
  if(where==='tank') cand=cand.filter(p=>p.sup==='42'||p.sup==='bat');
  if(S.power==='none') cand=cand.filter(p=>p.sup==='self'||p.sup==='bat');
  else cand=cand.filter(p=>p.sup!=='self'||where==='out');   // dieselmast ook als er wel stroom is, buiten
  if(S.power!=='none'&&where==='out') cand=cand.filter(p=>!(p.sup==='self'&&A<600)); // geen dieselmast voor een postzegel

  const typeOf=p=>p.sup==='self'?'zelfvoorzienend':p.sup==='bat'?'accu':/balloon/i.test(p.d)?'ballon':/tower|mast|pole/i.test(p.d)?'mast op net':/tube/i.test(p.d)?'buis':/Construction/i.test(p.d)?'bouwlamp':'schijnwerper';
  const scored=cand.map(p=>{
    const n=Math.max(1,Math.ceil(needLm/p.lm));
    const luxReal=n*p.lm*uf*MF/A;
    const spacing=Math.sqrt(A/n);
    // score: liefst 1–8 stuks, niet extreem overdimensioneren, zelfvoorzienend bij geen stroom
    let s=Math.abs(Math.log(n/3))*1.3 + Math.max(0,luxReal/lux-1.6)*0.8;
    if(n>12) s+=3; if(p.sup==='bat') s+=1.5;
    if(S.power==='none'&&p.sup==='self') s-=1;
    if(S.power!=='none'&&p.sup==='self') s+=0.6;
    return {p,n,luxReal,spacing,s,t:typeOf(p)};
  }).sort((a,b)=>a.s-b.s);

  if(!scored.length){
    $('vBig').textContent='Geen passende armatuur in de lijst';
    $('vWhy').textContent='Probeer een andere stroomkeuze of overleg met het depot.';
    $('planSvg').innerHTML='';$('planFacts').innerHTML='';return;
  }
  const best=scored[0];
  $('vBig').textContent=`${best.n}× ${short(best.p.d)}`;
  $('vWhy').textContent=`${f0(A)} m² op ${lux} lux vraagt ±${f0(needLm/1000)}k lumen. ${best.n} stuks geven ±${f0(best.luxReal)} lux; om de ±${f0(best.spacing)} m opstellen.${best.p.tip?' '+best.p.tip+'.':''}`;
  $('planSvg').innerHTML=areaSvg(Lm,Bm,best.n);
  $('planFacts').innerHTML=`<div class="k">Oppervlak</div><div class="v">${f0(A)} <small>m²</small></div>
    <div class="k">Gewenst</div><div class="v">${lux} <small>lux</small></div>
    <div class="k">Nodig</div><div class="v">${f0(needLm/1000)} <small>klm</small></div>
    <div class="k">Afstand tussen lampen</div><div class="v">±${f0(best.spacing)} <small>m</small></div>`;

  const seen=new Set(), shown=[];
  for(const o of scored){ if(seen.has(o.t))continue; seen.add(o.t); shown.push(o); if(shown.length===3)break; }
  shown.forEach((o,i)=>{
    const sp=supply(o.p.sup,o.n,o.p.W,ex);
    option(opts,i,`${o.n}× ${short(o.p.d)} → ±${f0(o.luxReal)} lux <small style="font-family:var(--sans);font-weight:400;color:#6b737b">· ${o.t}</small>`,[{qty:o.n,...o.p,sub:`${f0(o.p.lm)} lm · ${o.p.W} W per stuk${o.p.tip?' · '+o.p.tip:''}`},...sp.lines],sp.notes);
  });
}

/* ---------- weergave ---------- */
function short(d){return d.replace(/^(Lighting tower|Lightning tower|Floodlight|Construction lamp|LED light|Lighting mast|Lightingballoon|Light pole)\s*/,(m)=>({'Lighting tower':'Lichtmast ','Lightning tower':'Lichtmast ','Floodlight':'Schijnwerper ','Construction lamp':'Bouwlamp ','LED light':'LED-buis ','Lighting mast':'Lichtmast ','Lightingballoon':'Lichtballon ','Light pole':'Lichtmast '}[m.trim()]||m)).replace(/ incl\..*$/,'').replace(/ with.*$/,'');}
function option(host,i,title,lines,notes){
  const el=document.createElement('div');el.className='opt';
  el.innerHTML=`<div class="head"><span class="rank">${i===0?'Advies':'Optie '+(i+1)}</span><h3>${title}</h3><button type="button">Kopieer</button></div>`;
  lines.forEach((l,j)=>{const r=document.createElement('div');r.className='line'+(j>0?' sub':'');
    r.innerHTML=`<div class="qty">${l.qty}<small>×</small></div><div class="grp">${l.g}</div><div class="desc"><b>${l.d}</b>${l.sub||''}</div>`;el.appendChild(r);});
  notes.forEach(n=>{const r=document.createElement('div');r.className='line note';r.textContent=n;el.appendChild(r);});
  el.querySelector('button').addEventListener('click',()=>{
    const txt=lines.map(l=>`${l.qty}x ${l.g} - ${l.d}`).join('\n');
    navigator.clipboard?.writeText(txt).then(()=>{const t=$('toast');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1400);});
  });
  host.appendChild(el);
}
function areaSvg(L,B,n){
  const W=420,H=260,pad=34; const sc=Math.min((W-2*pad)/L,(H-2*pad)/B); const w=L*sc,h=B*sc,x0=pad+((W-2*pad)-w)/2,y0=(H-h)/2;
  const cols=Math.max(1,Math.round(Math.sqrt(n*L/B))), rows=Math.ceil(n/cols);
  let dots='';let k=0;
  for(let r=0;r<rows&&k<n;r++)for(let c=0;c<cols&&k<n;c++,k++){
    const cx=x0+w*(c+.5)/cols, cy=y0+h*(r+.5)/rows, rad=Math.min(w/cols,h/rows)*.55;
    dots+=`<circle cx="${cx}" cy="${cy}" r="${rad}" fill="#ffd166" opacity=".35"/><circle cx="${cx}" cy="${cy}" r="4" fill="#1b1f23"/>`;
  }
  return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Opstelling"><rect x="${x0}" y="${y0}" width="${w}" height="${h}" fill="#eef0f2" stroke="#1b1f23" stroke-width="2"/>${dots}
    <text x="${x0+w/2}" y="${y0-4}" text-anchor="middle" font-family="IBM Plex Mono,monospace" font-size="11" fill="#6b737b">${L} m</text>
    <text x="${x0-6}" y="${y0+h/2}" text-anchor="end" font-family="IBM Plex Mono,monospace" font-size="11" fill="#6b737b">${B} m</text></svg>`;
}
function pathSvg(L){
  const W=420,H=120; const n=Math.max(2,Math.min(12,Math.round(L/10)));
  let d='';for(let i=0;i<n;i++){const x=30+(W-60)*i/(n-1);d+=`<circle cx="${x}" cy="60" r="16" fill="#ffd166" opacity=".35"/><circle cx="${x}" cy="60" r="4" fill="#1b1f23"/>`;}
  return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Looppad"><line x1="20" y1="60" x2="${W-20}" y2="60" stroke="#1b1f23" stroke-width="2" stroke-dasharray="6 6"/>${d}<text x="${W/2}" y="105" text-anchor="middle" font-family="IBM Plex Mono,monospace" font-size="11" fill="#6b737b">${L} m</text></svg>`;
}

/* ---------- events ---------- */
function seg(id,key,attr,parse){$(id).addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;S[key]=parse?parse(b.dataset[attr]):b.dataset[attr];[...$(id).children].forEach(x=>x.classList.toggle('on',x===b));render();});}
seg('where','where','w');seg('task','lux','lux',Number);seg('power','power','p');
['lenA','widA','lenP','lux','uf','ex'].forEach(id=>$(id).addEventListener('input',render));
render();
})();
</script>
</body>
</html>

@endverbatim
